  question_106:{pl:"Długi krajów globalnego Południa wobec MFW i Banku Światowego powinny zostać anulowane.",en:"The debts of Global South countries to the IMF and World Bank should be cancelled.",a:5,b:5,c:0,d:10,e:0,f:0,g:5},
  question_107:{pl:"Prywatne banki powinny zostać znacjonalizowane.",en:"Private banks should be nationalized.",a:5,b:5,c:8,d:0,e:0,f:0,g:0},
  question_108:{pl:"Pracodawcy powinni być zobowiązani do przekazania pracownikom akcji firmy.",en:"Employers should be required to give workers company shares.",a:0,b:0,c:5,d:0,e:-5,f:0,g:0},
  question_109:{pl:"Sztuczna inteligencja powinna być własnością publiczną, a nie korporacyjną.",en:"Artificial intelligence should be publicly owned, not corporate.",a:5,b:0,c:5,d:0,e:0,f:0,g:5},
  question_110:{pl:"Kapitalizm i demokracja są ze sobą strukturalnie sprzeczne.",en:"Capitalism and democracy are structurally contradictory.",a:8,b:8,c:0,d:0,e:0,f:0,g:0},
  question_111:{pl:"Lewica powinna otwarcie mówić o komunizmie jako ostatecznym celu, nie tylko o socjalizmie.",en:"The left should openly speak about communism as the ultimate goal, not just socialism.",a:10,b:5,c:0,d:5,e:5,f:0,g:0,h:0},

  // ========== OŚ H: EMANCYPACJA ↔ WSPÓLNOTOWOŚĆ ==========
  question_112:{pl:"Emancypacja kobiet jest integralną częścią walki klasowej i nie można jej odkładać na 'po rewolucji'.",en:"Women's emancipation is an integral part of the class struggle and cannot be deferred until 'after the revolution'.",a:0,b:5,c:0,d:5,e:0,f:0,g:5,h:10},
  question_113:{pl:"Tożsamość płciowa jest kwestią prywatną i nie powinna dominować lewicowej agendy politycznej.",en:"Gender identity is a private matter and should not dominate the left-wing political agenda.",a:0,b:0,c:0,d:0,e:0,f:0,g:-5,h:-8},
  question_114:{pl:"Walka z seksizmem i rasizmem jest równie ważna jak walka z wyzyskiem klasowym.",en:"The struggle against sexism and racism is equally important as the struggle against class exploitation.",a:0,b:0,c:0,d:5,e:-5,f:0,g:8,h:10},
  question_115:{pl:"Tradycyjne role płciowe mogą być dobrowolnie wybierane i powinny być szanowane przez lewicę.",en:"Traditional gender roles can be voluntarily chosen and should be respected by the left.",a:0,b:0,c:0,d:0,e:0,f:0,g:-5,h:-10},
  question_116:{pl:"System patriarchatu jest strukturalnym problemem, który musi być rozmontowany przez politykę lewicy.",en:"Patriarchy is a structural problem that must be dismantled through left-wing politics.",a:0,b:5,c:0,d:0,e:0,f:0,g:8,h:10},
  question_117:{pl:"Ruchy #MeToo i feminizm czwartej fali wniosły istotny wkład w walkę o sprawiedliwość społeczną.",en:"#MeToo movements and fourth-wave feminism have made an important contribution to the fight for social justice.",a:0,b:0,c:0,d:0,e:0,f:0,g:8,h:10},
  question_118:{pl:"Lewica zbyt mocno skupia się na kwestiach tożsamościowych kosztem problemów klasowych i ekonomicznych.",en:"The left focuses too much on identity issues at the expense of class and economic problems.",a:0,b:5,c:0,d:0,e:5,f:0,g:-5,h:-8},
  question_119:{pl:"Praca domowa i opieka nad dziećmi powinna być wynagradzana lub wspierana przez państwo.",en:"Domestic work and childcare should be compensated or supported by the state.",a:0,b:0,c:5,d:0,e:5,f:0,g:5,h:10},
  question_120:{pl:"Lewica powinna priorytetyzować solidarność klasową nad solidarnością genderową.",en:"The left should prioritize class solidarity over gender solidarity.",a:5,b:5,c:0,d:0,e:5,f:0,g:0,h:-8},
  question_121:{pl:"Dekolonizacja i feminizm postkolonialny powinny być integralną częścią lewicowej teorii.",en:"Decolonization and postcolonial feminism should be an integral part of left-wing theory.",a:0,b:0,c:0,d:8,e:-5,f:0,g:8,h:10},
  question_122:{pl:"Wyzwolenie seksualne jest częścią szerszego projektu emancypacji politycznej.",en:"Sexual liberation is part of a broader project of political emancipation.",a:0,b:0,c:0,d:5,e:0,f:0,g:10,h:10},
  question_123:{pl:"Państwo powinno aktywnie promować równość płci w instytucjach publicznych.",en:"The state should actively promote gender equality in public institutions.",a:0,b:0,c:5,d:0,e:5,f:0,g:8,h:10},
  question_124:{pl:"Ochrona macierzyństwa i rodzicielstwa powinna być priorytetem polityki społecznej.",en:"Protection of maternity and parenthood should be a priority of social policy.",a:0,b:0,c:5,d:0,e:5,f:0,g:0,h:5},
  question_125:{pl:"Kultura popularna i media odgrywają ważną rolę w utrwalaniu lub kwestionowaniu stereotypów płciowych.",en:"Popular culture and media play an important role in reinforcing or challenging gender stereotypes.",a:0,b:0,c:0,d:0,e:0,f:0,g:8,h:8},
  question_126:{pl:"Anarchofeminizm słusznie łączy krytykę patriarchatu z krytyką państwa i kapitalizmu.",en:"Anarcho-feminism rightly combines criticism of patriarchy with criticism of the state and capitalism.",a:5,b:0,c:-5,d:5,e:-5,f:0,g:8,h:10},
  question_127:{pl:"Komunitaryzm i tradycyjne więzi społeczne mogą być wartościowe dla budowania lewicowej wspólnoty.",en:"Communitarianism and traditional social bonds can be valuable for building a left-wing community.",a:0,b:0,c:0,d:-5,e:0,f:0,g:-5,h:-5},
  question_128:{pl:"Lewica powinna bronić prawa do aborcji jako kwestii zdrowia reprodukcyjnego, nie moralnej.",en:"The left should defend abortion rights as a reproductive health issue, not a moral one.",a:0,b:0,c:0,d:5,e:0,f:0,g:10,h:10},
  question_129:{pl:"Socjalizm bez feminizmu jest niekompletny — nie możemy wyzwolić klasy nie wyzwalając kobiet.",en:"Socialism without feminism is incomplete — we cannot liberate the class without liberating women.",a:0,b:5,c:0,d:5,e:0,f:0,g:8,h:10},
